n.push(A.K("\u2192 github.com/xynorash/heaplens \xb7 crates/heaplens-alloc/examples/checkout_service_gui.rs","https://github.com/xynorash/heaplens/blob/master/crates/heaplens-alloc/examples/checkout_service_gui.rs"))
