o.push(B.b)
B.a.h(o,A.i("Everything that runs a command uses argv lists, never a shell string, and every crate name, feature name and package name from the network or from a file is validated before it reaches one. That sentence is in the code comments of all three modules, and tests in the repository try hostile names such as --git, -p, $(x) and ../x."))
o.push(B.b)
B.a.h(o,A.b("the repository, file by file"))
o.push(A.p("xyno-crates.nvim/"))
o.push(A.p("\u251c\u2500\u2500 README.md                    this page"))
