B.a.h(n,A.b("the manifest editor: exact text in, exact text out"))
B.a.h(n,A.d(o,"tests/crate-features_spec.lua \xb7 lines 327-343",'  it("turns a version string into an inline table", function()\n    local out = edit(\'[dependencies]\\nserde = "1" # keep\\nrand = "0.8"\\n\', "serde", "add", { "derive" })\n    H.eq(\'[dependencies]\\nserde = { version = "1", features = ["derive"] } # keep\\nrand = "0.8"\\n\', out)\n  end)\n\n  it("appends to an existing features array and to an inline table without one", function()\n    H.eq(\'[dependencies]\\ntokio = { version = "1", features = ["rt", "macros"] }\\n\', (edit(\'[dependencies]\\ntokio = { version = "1", features = ["rt"] }\\n\', "tokio", "add", { "macros" })))\n    H.eq(\'[dependencies]\\nx = { version = "1", default-features = false, features = ["a"] }\\n\', (edit(\'[dependencies]\\nx = { version = "1", default-features = false }\\n\', "x", "add", { "a" })))\n    H.eq(\'[dependencies]\\nx = { features = ["a"] }\\n\', (edit("[dependencies]\\nx = { }\\n", "x", "add", { "a" })))\n    H.eq(\'[dependencies]\\nserde = { workspace = true, features = ["derive"] } # c\\n\', (edit("[dependencies]\\nserde = { workspace = true } # c\\n", "serde", "add", { "derive" })))\n  end)\n\n  it("keeps a multi-line array\'s layout, comments and trailing comma", function()\n    local src = \'[dependencies]\\ntokio = { version = "1", features = [\\n    "rt", # runtime\\n    "net",\\n] }\\n\'\n    local out = edit(src, "tokio", "add", { "macros" })\n    H.eq(\'[dependencies]\\ntokio = { version = "1", features = [\\n    "rt", # runtime\\n    "net",\\n    "macros",\\n] }\\n\', out)\n  end)'))
B.a.h(n,A.a(q,'Every edit test compares complete strings. A version string becomes an inline table and the trailing comment "# keep" survives. An inline table without features gains the key, a table with an array extends it, an empty inline table is filled, workspace = true gets features after it. A multi-line array keeps its indentation, its comment, and its trailing comma. These are the tests that make the claim "formatting and comments kept" falsifiable.'))
