B.a.h(n,A.b("the real one"))
B.a.h(n,A.d(o,"tests/crate-import_spec.lua \xb7 lines 361-381",'describe("real: Uuid from nothing", function()\n  it("search, add the crate, wait for rust-analyzer, import, cargo build", function()\n    H.known_issue({ "windows" }, "live rust-analyzer flow fails or hangs on Windows (windows-latest run 39647013043; cause not diagnosed)")\n    H.need_rust()\n    local info = cm.info("uuid", { index_only = true })\n    if not info then\n      return skip("crates.io is not reachable")\n    end\n    local dir = H.fixture("no-deps-lab")\n    vim.cmd.cd(vim.fn.fnameescape(dir))\n    local buf = H.open(dir .. "/src/main.rs")\n    H.start_ra(buf, dir)\n    ci.setup()\n    local res\n    E.resolve("Uuid", {\n      bufnr = buf,\n      cb = function(r)\n        res = r\n      end,\n    })\n    H.wait_for(function()'))
B.a.h(n,A.a(q,'"real: Uuid from nothing" copies the no-deps-lab fixture, starts a real rust-analyzer on it (H.start_ra, the line that replaced H.wait_lsp at the extraction), registers the source, asks the engine to resolve the name Uuid and waits up to a minute. It finds uuid::Uuid among the candidates and asserts that it is marked add_crate and guess: the label survives the full path.'))
n.push(B.b)
B.a.h(n,A.d(o,"tests/crate-import_spec.lua \xb7 lines 392-407",'    local done, ok, msg\n    E.apply_candidate(buf, cand, function(a, b)\n      done, ok, msg = true, a, b\n    end)\n    H.wait_for(function()\n      return done\n    end, 120000, "add and import")\n    H.eq(true, ok, tostring(msg))\n    local text = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), "\\n")\n    H.match(text, "use uuid::Uuid;", true)\n    local toml = table.concat(vim.fn.readfile(dir .. "/Cargo.toml"), "\\n")\n    H.match(toml, "uuid", true)\n    vim.cmd("silent write")\n    local r = vim.system({ "cargo", "check", "--quiet", "--target-dir", H.tmpdir() }, { cwd = dir, text = true }):wait(170000)\n    H.eq(0, r.code, (r.stderr or ""):sub(-1500))\n  end)'))
B.a.h(n,A.a(q,"Then it applies the candidate and waits up to two minutes for add, load and import. The text of the buffer must contain use uuid::Uuid;, Cargo.toml must mention uuid, and after writing the file cargo check --quiet in the fixture directory must exit with 0. On Windows the test is a known issue with the CI run number; without network, cargo or rust-analyzer it skips with a reason. It is slow on purpose, the only test in the file that touches the world."))
