p.push(A.p("\u251c\u2500\u2500 data/macro_attrs/"))
p.push(A.p("\u2502   \u251c\u2500\u2500 README.md     the schema format"))
p.push(A.p("\u2502   \u2514\u2500\u2500 serde, clap, tokio, sqlx, thiserror, derive_more, strum, bon, schemars, utoipa .json"))
p.push(A.p("\u251c\u2500\u2500 tests/"))
