B.a.h(n,A.a(q,"Two caveats apply to the whole table. Everything is warm: a cold cargo cache is not measured anywhere in the notes. And the figures come from one machine and a small workspace, recorded by the author in the CHANGELOG, not produced by a script in this repository that a reader could re-run."))
B.a.h(n,A.b("how the file grew"))
n.push(A.f(q,"  09-03 07:05  3ec11c4  32 lines. cargo backend, clippy with"))
n.push(A.f(q,"                        --workspace --all-targets --all-features,"))
n.push(A.f(q,"                        updateOnInsert in init_options + settings."))
n.push(A.f(q,"  09-03 19:54  f35b4f6  checkOnSave off, --all-targets dropped,"))
n.push(A.f(q,"                        --no-deps added, debounce 800, and the"))
n.push(A.f(q,"                        \u201cmust stay ON\u201d comment from the A/B test."))
n.push(A.f(q,"  09-04 01:18  0715b98  cmd override to the patched 0.29.0 build;"))
