B.a.h(n,A.c(q,"b2fee5c (2026-10-13)","created. 98c9bb4, a3d33c8, 25086fd :: field test rounds."))
B.a.h(n,A.c(q,"fc2062a, dc846f6 (2026-10-14)","CI on a clean machine, 40 minute timeout."))
